import os
import torch
from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
from peft import LoraConfig, PeftModel, get_peft_model, prepare_model_for_kbit_training

from dialogue_kt.utils import get_checkpoint_path

bnb_config = BitsAndBytesConfig(
    load_in_8bit=True,
)

def get_base_model(base_model_name: str, tokenizer: AutoTokenizer, quantize: bool):
    _kwargs = dict(
        quantization_config=bnb_config if quantize else None,
        # f32 seems helpful for train/test time consistency when quantizing, bf16 performs best for non-quantized
        torch_dtype=torch.float32 if quantize else torch.bfloat16,
        # Fork change. DDP (torchrun): each rank loads the model on its own GPU. Single-GPU
        # runs are unchanged (LOCAL_RANK defaults to 0).
        device_map={"": int(os.environ.get("LOCAL_RANK", "0"))}
    )
    try:
        base_model = AutoModelForCausalLM.from_pretrained(base_model_name, **_kwargs)
    except ValueError:
        # Fallback for text models packaged only as a ...ForConditionalGeneration wrapper (e.g.
        # Ministral-3-*).
        from transformers import AutoModelForImageTextToText
        base_model = AutoModelForImageTextToText.from_pretrained(base_model_name, **_kwargs)
    # pad_token_id is set on the loaded config, not passed to from_pretrained (some backbones
    # reject it as a kwarg under transformers 5.x); the two are equivalent.
    base_model.config.pad_token_id = tokenizer.pad_token_id
    base_model.config.use_cache = False
    base_model.config.pretraining_tp = 1
    return base_model

def get_model(base_model_name: str, test: bool,
              model_name: str = None, pt_model_name: str = None,
              r: int = None, lora_alpha: int = None,
              quantize: bool = True, use_gradient_checkpointing: bool = True):
    tokenizer = AutoTokenizer.from_pretrained(base_model_name, padding_side="right")
    # Original (Llama): pad with bos (eos triggers a warning). Qwen3 has bos_token=None
    # but ships a valid pad_token (<|endoftext|>), so keep the tokenizer's own pad token
    # for models without a bos; fall back to eos only if neither is defined.
    if tokenizer.bos_token is not None:
        tokenizer.pad_token = tokenizer.bos_token
    elif tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    model = get_base_model(base_model_name, tokenizer, quantize)
    if test and model_name:
        # Note we are loading adapter on quantized model and not merging
        # Recommended here - https://huggingface.co/docs/trl/main/en/dpo_trainer#downsides-to-merging-qlora-before-dpo-approach-2
        # Also prevents empty responses generated by Llama models
        print("Initializing inference-time model from fine-tuned LoRA adapters")
        model = PeftModel.from_pretrained(model, get_checkpoint_path(model_name))
    elif not test:
        if quantize:
            model = prepare_model_for_kbit_training(model, use_gradient_checkpointing=use_gradient_checkpointing)
        elif use_gradient_checkpointing and os.environ.get("LLMKT_GRAD_CKPT", "1") != "0":
            # Fork change. On the bf16 (non-quantized) path prepare_model_for_kbit_training is
            # skipped, so upstream never turns gradient checkpointing on; without it, activation
            # memory across the 28 decoder layers runs out of memory even on an 80GB A100 with
            # long Trace the Ace dialogues. Enable it here.
            #
            # LLMKT_GRAD_CKPT=0 turns it off; the pipeline uses the default (on).
            # enable_input_require_grads() is required so checkpointing has a gradient path
            # through the frozen (LoRA) base; use_cache is already False in get_base_model.
            if int(os.environ.get("WORLD_SIZE", "1")) > 1:
                # non-reentrant checkpointing composes cleanly with DDP autograd hooks
                model.gradient_checkpointing_enable(gradient_checkpointing_kwargs={"use_reentrant": False})
            else:
                model.gradient_checkpointing_enable()
            model.enable_input_require_grads()
        if pt_model_name:
            print("Initializing trainable model from pre-trained LoRA adapters")
            model = PeftModel.from_pretrained(model, get_checkpoint_path(pt_model_name), is_trainable=True, adapter_name="default")
        else:
            print("Initializing trainable model with new LoRA adapters")
            _proj = "q_proj|k_proj|v_proj|o_proj|gate_proj|up_proj|down_proj"
            if hasattr(model, "language_model") or (getattr(model.config, "architectures", None)
                    and "ForConditionalGeneration" in model.config.architectures[0]):
                # Multimodal wrapper (e.g. Ministral-3): attach adapters to the language model
                # only, not the vision tower.
                _targets = rf".*language_model.*\.({_proj})"
            else:
                _targets = _proj.split("|")
            peft_config = LoraConfig(
                target_modules=_targets,
                r=r,
                lora_alpha=lora_alpha,
                lora_dropout=0.05,
                task_type="CAUSAL_LM",
                inference_mode=False,
            )
            model = get_peft_model(model, peft_config)
    else:
        print("Initializing inference-time model from pre-trained weights")

    # Fork change. LLMKT_COMPILE=1 wraps the model in torch.compile(dynamic=True). It is off by
    # default.
    if os.environ.get("LLMKT_COMPILE") == "1":
        import time as _t
        _t0 = _t.perf_counter()
        model = torch.compile(model, dynamic=True)
        print(f"[compile] torch.compile(dynamic=True) wrapped in {_t.perf_counter() - _t0:.1f}s "
              f"(kernels compile lazily on the first steps)")
    return model, tokenizer
